for c in [0,3,5,8,9]:
    m = a==c
    lab,n = ndimage.label(m, structure=np.ones((3,3)))
    for i in range(1,n+1):
        ys,xs = np.where(lab==i)
        sub = a[ys.min():ys.max()+1, xs.min():xs.max()+1]
        sub = np.where(sub==c, 1, 0)
        print('color',c,'bbox rows',ys.min(),ys.max(),'cols',xs.min(),xs.max())
        for r in sub: print(''.join('#' if v else '.' for v in r))
        print()
